function historyFilteredRows(session){let stage=historyStages.get(session.key);if(stage&&!session.rows.some(row=>ExamHistory.stage(row).key===stage)){historyStages.delete(session.key);historyPages.delete(session.key);stage=''}return stage?session.rows.filter(row=>ExamHistory.stage(row).key===stage):session.rows}
