function render(){let q=norm($('#search').value),city=$('#city').value,session=$('#history-session').value,type=$('#type').value,result=$('#result').value,items=state.items.filter(x=>(!q||norm([x.nome_aluno,x.comum,x.instrumento].join(' ')).includes(q))&&(!city||x.municipio===city)&&(!session||ExamHistory.sessionKey(x)===session)&&(!type||x.tipo_exame===type)&&(!result||x.resultado===result)),groups=ExamHistory.group(items),sessions=groups.reduce((n,g)=>n+g.sessions.length,0);historySessions=new Map();$('#count').textContent=`${items.length} registros · ${groups.length} ${groups.length===1?'administração':'administrações'} · ${sessions} ${sessions===1?'exame':'exames'}`;let index=0;$('#body').innerHTML=groups.length?groups.map(g=>`<details class="exam-administration" data-administration="${esc(g.label)}" ${q||openHistoryAdmin===g.label?'open':''}><summary><strong><i class="fa fa-location-dot text-danger me-1" aria-hidden="true"></i>${esc(g.label)}</strong><small>${g.count} ${g.count===1?'registro':'registros'} · ${g.sessions.length} ${g.sessions.length===1?'exame':'exames'}</small></summary>${['Músicos','Organistas'].map(category=>{let list=g.sessions.filter(x=>x.category===category);return list.length?`<section class="exam-category"><h6><i class="fa ${category==='Organistas'?'fa-keyboard':'fa-music'} me-1" aria-hidden="true"></i>${category}</h6>${list.map(session=>{let token='h'+index++;historySessions.set(token,session);return `<details class="exam-session" data-session="${token}" ${q||openHistorySession===session.key?'open':''}><summary><span class="exam-session-date"><i class="fa fa-calendar-days me-1" aria-hidden="true"></i>${session.day?date(session.day):'Data não informada'}</span><span class="exam-session-types">${ExamHistory.levels(session.rows).map(level=>`${level.rows.length} ${esc(level.label)}`).join(' · ')}</span><span class="exam-session-count"><i class="fa fa-circle-check me-1" aria-hidden="true"></i>${session.approved} ${session.category==='Organistas'?'aprovadas':'aprovados'} / ${session.rows.length} registros</span></summary><div data-history-content="${token}"></div></details>`}).join('')}</section>`:''}).join('')}</details>`).join(''):'<div class="empty">Nenhum exame encontrado neste recorte.</div>';document.querySelectorAll('.exam-session[open]').forEach(d=>renderHistorySession(d.dataset.session))}
