$('#body').addEventListener('change',e=>{let input=e.target;if(!input.matches('.history-select-record,.history-select-page'))return;let session=historySessions.get(input.dataset.session);if(!session)return;let selection=historySelection(session);if(input.matches('.history-select-page')){let page=historyPageInfo(session);page.rows.forEach(row=>input.checked?selection.add(String(row.id)):selection.delete(String(row.id)))}else{input.checked?selection.add(input.dataset.id):selection.delete(input.dataset.id)}updateHistorySelection(input.dataset.session)});
