async function deleteHistoryGroup(token,mode){if(historyDeleteBusy)return;let session=historySessions.get(token);if(!session)return;let ids=[...historySelection(session)];if(mode==='selecionados'&&!ids.length)return;historyDeleteBusy=true;let notice=summaryToast('loading','Conferindo exclusão','Localizando os registros deste exame.');try{async function send(body){let response=await fetch('/musica/exames/api/excluir-grupo/',{method:'POST',headers:{'Content-Type':'application/json','X-CSRFToken':csrf()},body:JSON.stringify(body)}),result=await response.json();if(!response.ok)throw Error(result.error||'Não foi possível excluir os registros.');return result}let preview=await send({acao:'previa',modo:mode,grupo:{administracao:session.administration,categoria:session.category,data_exame:session.day},ids});notice.close();let context=`${session.administration} · ${session.category} · ${date(session.day)}. Serão excluídos ${preview.quantidade} registros. ${mode==='todos'?'Inclui todas as páginas e os registros deste exame fora dos filtros atuais. ':''}Os cadastros e o nível atual dos alunos serão mantidos.`;if(!await gemConfirm(mode==='todos'?'Excluir o grupo inteiro?':'Excluir os selecionados?',context,`Excluir ${preview.quantidade} registros`))return;let result={restantes:preview.quantidade,excluidos:0};while(result.restantes>0){notice=summaryToast('loading','Excluindo registros',`${result.excluidos} de ${preview.quantidade} registros excluídos. Atualizando histórico e quadro.`);result=await send({acao:'confirmar',token:preview.token});notice.close()}historySelections.delete(session.key);await load();summaryToast('success','Registros excluídos',`${result.excluidos} registros removidos. Histórico e totais atualizados.`)}catch(error){notice.close();await load();examNotice('danger',error.message)}finally{historyDeleteBusy=false;notice.close()}}
