function renderStudentOptions(){let select=$('#student'),selected=select.value,control=jQuery(select),student=state.students.find(x=>String(x.id)===selected);if(control.hasClass('select2-hidden-accessible'))return;select.innerHTML='<option value=""></option>';if(student)select.add(new Option(`${student.nome} · ${student.municipio} · ${student.instrumento||''}`,student.id,true,true));control.select2({width:'100%',language:'pt-BR',placeholder:'Digite pelo menos 2 letras do nome…',minimumInputLength:2,dropdownParent:jQuery('#record-modal'),dropdownCssClass:'exam-student-dropdown',ajax:{url:'/musica/exames/api/alunos/',dataType:'json',delay:300,data:params=>({q:params.term}),processResults:data=>({results:data.items.map(student=>({...student,text:`${student.nome} · ${student.municipio} · ${student.instrumento||'A definir'}`}))})}});control.on('select2:select',e=>{let student=e.params.data;if(!state.students.some(x=>String(x.id)===String(student.id)))state.students.push(student);updateExamTypes();loadAgenda()})}
