function filterParams(){let p=new URLSearchParams(),map={'op-year':'ano','op-event':'evento','op-common':'comum','op-city':'municipio','op-month':'mes','op-start':'inicio','op-end':'fim','op-launch-start':'lancamento_inicio','op-launch-end':'lancamento_fim'};Object.entries(map).forEach(([id,key])=>{let v=$('#'+id)?.value;if(v)p.set(key,v)});return p} async function load(){try{let params=filterParams(),r=await fetch('/musica/exames/api/dashboard/?'+params,{cache:'no-store'}),d=await r.json();if(!r.ok)throw Error(d.error);state=d;let available=new Set(state.items.map(row=>String(row.id)));historySelections.forEach(set=>[...set].forEach(id=>{if(!available.has(id))set.delete(id)}));managementOptions();metrics();renderGroups();options();render();$("#excel").href="/musica/exames/exportar-excel/?"+filterParams()}catch(e){$('#notice').innerHTML=`<div class="alert alert-danger">${esc(e.message)}</div>`;$('#body').innerHTML='<div class="empty">Não foi possível carregar.</div>'}}
