function importRender(d){importPreview=d;if(!$('#import-date').value){let days=[...new Set(d.items.map(r=>r.data_exame).filter(Boolean))];if(days.length===1)$('#import-date').value=days[0]}importBatchOptions();$('#import-result').innerHTML=`<div id="import-summary" class="import-overview" aria-live="polite"></div><div class="import-stage-counts">${Object.entries(d.items.reduce((counts,r)=>{counts[r.tipo_exame||'Sem etapa']=(counts[r.tipo_exame||'Sem etapa']||0)+1;return counts},{})).map(([kind,total])=>`<span><strong>${total}</strong> ${esc(kind)}</span>`).join('')}</div><details class="import-review"><summary>Conferir nomes e resultados (${d.items.length})</summary><div class="import-list-tools"><input id="import-search" type="search" class="form-control" placeholder="Buscar aluno(a) ou comum…" aria-label="Buscar aluno(a) ou comum"><label class="small text-nowrap"><input id="import-only-pending" type="checkbox" class="form-check-input me-1"> Só pendências</label><label class="small text-nowrap"><input id="import-select-all" type="checkbox" class="form-check-input me-1" checked> Selecionar visíveis</label></div>${d.warning?`<details class="import-note"><summary>Cuidados com a leitura do arquivo</summary><p class="mt-2">${esc(d.warning)}</p></details>`:''}<table class="table import-list mb-0"><tbody>${d.items.map((r,i)=>`<tr data-line="${i}" data-search="${esc(r.nome+' '+r.comum)}"><td><input type="checkbox" class="form-check-input import-check" checked aria-label="Incluir ${esc(r.nome)}"></td><td><details class="import-item"><summary><span class="import-person"><strong>${esc(r.nome)}</strong><small>${esc(r.comum)}<span class="import-individual-date"></span></small></span><span class="import-summary-kind">${esc(r.tipo_exame)}</span><span class="import-summary-result">${status(r.resultado,r)}</span><span class="import-row-status"></span><span class="import-adjust"><i class="fa fa-pen me-1" aria-hidden="true"></i>Ajustar</span></summary><div class="import-edit-grid"><div><label>Cadastro correspondente</label><select aria-label="Cadastro de ${esc(r.nome)}" class="form-select import-student"><option value="">Selecione o cadastro…</option>${(r.candidates||[]).map(x=>`<option value="${esc(x.id)}" ${String(x.id)===r.aluno_id?'selected':''}>${esc(x.nome)} · ${Number(x.score)}%</option>`).join('')}${!(r.candidates||[]).length?`<option value="__new__" selected>Cadastrar ${esc(r.nome)}</option>`:''}</select><small class="import-location"></small><label class="small d-block mt-2 import-rename-label"><input type="checkbox" class="import-rename" checked> Atualizar nome conforme o documento</label><div class="import-new-fields mt-2" hidden><label>Categoria</label><select aria-label="Categoria" class="form-select import-category"><option value="ORGANISTA" ${r.categoria==='ORGANISTA'?'selected':''}>Organista</option><option value="MÚSICO" ${r.categoria!=='ORGANISTA'?'selected':''}>Músico</option></select><label>Instrumento (para músico)</label><input aria-label="Instrumento" class="form-control import-instrument" value="${esc(r.instrumento||'')}"></div></div><div><label>Etapa</label><select aria-label="Etapa" class="form-select import-kind"><option value="">Selecione…</option>${['RJM','CULTO OFICIAL','OFICIALIZAÇÃO','TESTE EMERGENCIAL','TROCA DE INSTRUMENTO'].map(x=>`<option ${x===r.tipo_exame?'selected':''}>${x}</option>`).join('')}</select><label class="mt-2">Resultado</label><select aria-label="Resultado" class="form-select import-result-value">${['AGENDADO','APROVADO','RETORNOU AO CICLO','AUSENTE'].map(x=>`<option value="${x}" ${x===r.resultado?'selected':''}>${esc(ExamHistory.resultLabel(x,r))}</option>`).join('')}</select></div><div><label>Data individual</label><input aria-label="Data individual" type="date" class="form-control import-day" value="${esc($('#import-date').value||r.data_exame)}"><label class="mt-2">Evento individual</label><select aria-label="Evento individual" class="form-select import-event"></select><label class="small mt-2"><input type="checkbox" class="import-historical"> Histórico sem evento na agenda</label></div></div></details></td></tr>`).join('')}</tbody></table><div id="import-empty" class="import-empty" hidden>Nenhum aluno ou aluna neste filtro.</div></details>`;$('#import-search').oninput=importFilter;$('#import-only-pending').onchange=importFilter;$('#import-select-all').onchange=e=>{document.querySelectorAll('#import-result tr[data-line]').forEach(tr=>{if(!tr.hidden)tr.querySelector('.import-check').checked=e.target.checked});importFilter()};document.querySelectorAll('#import-result tr[data-line]').forEach(tr=>{importEvents(tr);tr.querySelectorAll('input,select').forEach(x=>x.addEventListener('change',()=>{if(x.matches('.import-student,.import-day,.import-category'))importEvents(tr);importSummary(tr)}));importSummary(tr)});importApplyBatch(true);$('#import-preview').textContent='Ler outro arquivo'}
$('#import-apply').onclick=()=>importApplyBatch(true);
$('#import-date').addEventListener('change',()=>{importBatchOptions();importApplyBatch()});
$('#import-batch-event').onchange=()=>{let event=importPreview?.events.find(e=>e.id===$('#import-batch-event').value);if(event){$('#import-date').value=event.data;importBatchOptions()}importApplyBatch()};
$('#import-default-result').onchange=()=>importApplyBatch(true);
$('#import-form').onsubmit=async e=>{e.preventDefault();let button=e.submitter,old=button.innerHTML;button.disabled=true;button.innerHTML='<i class="fa fa-spinner fa-spin"></i> Lendo arquivo';let notice=summaryToast('loading','Lendo documento','Preparando a conferência dos resultados.');try{let r=await fetch('/musica/exames/api/importar/',{method:'POST',headers:{'X-CSRFToken':csrf()},body:new FormData(e.target),signal:AbortSignal.timeout(90000)}),d=await r.json();if(!r.ok)throw Error(d.error);importRender(d);notice.close()}catch(x){notice.close();examNotice('danger',x.name==='TimeoutError'?'A leitura excedeu 90 segundos. Tente novamente; nenhuma linha foi gravada.':x.message)}finally{button.disabled=false;button.innerHTML=old}};
$('#import-commit').onclick=async()=>{if(!importPreview)return;let button=$('#import-commit'),old=button.innerHTML,items=[...document.querySelectorAll('#import-result tr[data-line]')].filter(tr=>tr.querySelector('.import-check').checked).map(tr=>({linha:Number(tr.dataset.line),aluno_id:tr.querySelector('.import-student').value,criar_cadastro:tr.querySelector('.import-student').value==='__new__',atualizar_nome:tr.querySelector('.import-rename').checked,categoria:tr.querySelector('.import-category').value,instrumento:tr.querySelector('.import-instrument').value,tipo_exame:tr.querySelector('.import-kind').value,resultado:tr.querySelector('.import-result-value').value,data_exame:tr.querySelector('.import-day').value,agenda_evento_id:tr.querySelector('.import-event').value,historico_sem_agenda:tr.querySelector('.import-historical').checked}));button.disabled=true;button.innerHTML='<i class="fa fa-spinner fa-spin"></i> Gravando';let notice=summaryToast('loading','Importando resultados',`${items.length} resultados enviados juntos. Salvando exames e atualizando o quadro e os níveis.`);try{async function send(part,validate=false){let r=await fetch('/musica/exames/api/importar/',{method:'POST',headers:{'Content-Type':'application/json','X-CSRFToken':csrf()},body:JSON.stringify({token:importPreview.token,items:part,validar_apenas:validate})}),body=await r.json();if(!r.ok||!body.ok)throw Error([body.error,...(body.errors||[]).map(x=>`Linha ${Number(x.linha)+1}: ${x.error}`)].filter(Boolean).join(' '));return body}let d=await send(items);await load();notice.close();bootstrap.Modal.getInstance($('#import-modal')).hide();examNotice('success',`${d.importados} importados; ${d.duplicados} já registrados; ${d.cadastrados||0} cadastros novos; ${d.nomes_atualizados||0} nomes atualizados.`)}catch(x){notice.close();examNotice('danger',x.message)}finally{button.disabled=false;button.innerHTML=old}};
function historyParams(){let p=filterParams();p.set('historico','1');[['search','q'],['city','cidade_individual'],['type','tipo_individual'],['result','resultado_individual'],['history-session','sessao_individual']].forEach(([id,key])=>{if($('#'+id).value)p.set(key,$('#'+id).value)});return p}
$('#history-excel').onclick=e=>{e.currentTarget.href='/musica/exames/exportar-excel/?'+historyParams()};
$('#history-pdf').onclick=()=>window.open('/musica/exames/exportar-pdf/?'+historyParams(),'_blank','noopener');
